import React from "react";
import styled from "styled-components";
import { Tablet } from "../Responsive";
import { HashLink as Link } from "react-router-hash-link";

const Wrapper = styled.div`
  font-family: var(--primary-font);

  .navbar{
    background: white;
    box-shadow: 0px 5px 5px rgba(0, 0, 0, 0.20);
  }

  .first-nav {
    ${Tablet({
  background: "#ffffff",
  borderRadius: "30px",
  padding: "4px",
  paddingRight: "20px",
  paddingLeft: "20px"
})}
  }
  .first-nav li a {
    color: var(--primary-color);
    font-weight: 500;
  }
`;

function Header() {
  return (
    <Wrapper className="sticky-top">
      <nav class="navbar navbar-expand-sm navbar-light">
        <div class="container-fluid">
          <Link class="navbar-brand" to="/">
            <img src="/images/brand.png" alt="Kintik Resort" width="30" height="30" class="d-inline-block align-text-top" />
            Ahom Hotel
          </Link>
          <button
            class="navbar-toggler"
            type="button"
            data-bs-toggle="collapse" data-bs-target="#navbarTogglerDemo02"
            aria-controls="navbarTogglerDemo02"
            aria-expanded="false"
            aria-label="Toggle navigation"
          >
            <span class="navbar-toggler-icon"></span>
          </button>
          <div class="collapse navbar-collapse" id="navbarTogglerDemo02">
            <ul class="navbar-nav m-auto mb-2 mb-lg-0">
              <li class="nav-item">
                <Link class="nav-link" to="/">Home</Link>
              </li>
              <li class="nav-item">
                <Link class="nav-link" to="/gallery">Gallery</Link>
              </li>
              <li class="nav-item">
                <Link class="nav-link" to="/contact-us">Contact Us</Link>
              </li>
              <li class="nav-item">
                <Link class="nav-link" to="/rooms/all">Rooms</Link>
              </li>
            </ul>


          </div>
        </div>
      </nav>

    </Wrapper>
  );
}

export default Header;
